use byond_dmb::{bytecode,dmb::{Dmb,DmString},operands::Variable as V};use std::{env,fs,path::PathBuf,collections::BTreeMap};
fn main()->Result<(),Box<dyn std::error::Error>>{let a=env::args().collect::<Vec<_>>();let input=PathBuf::from(&a[1]);let output=PathBuf::from(&a[2]);let mut d=Dmb::from_bytes(&fs::read(&input)?)?;let log=d.strings.iter().position(|s|s.data==b"log").unwrap()as u32;let id=d.procs.iter().position(|p|d.string(p.strings[0])==Some(b"/proc/dq_type_storage_cost")).ok_or("cost")?;let old=d.proc_code_words(id).unwrap().to_vec();let dec=bytecode::decode(&old).map_err(|e|format!("{e:?}"))?;let mut w=vec![];let mut map=BTreeMap::new();let mut branches=vec![];for i in &dec{map.insert(i.offset,w.len());for at in i.branch_target_word_offsets().map_err(|e|format!("{e:?}"))?{branches.push((w.len()+at-i.offset,old[at]as usize));}w.push(i.opcode);w.extend(&i.operands);if [0x29,0x30].contains(&i.opcode){if d.strings.len()==65535{d.strings.push(DmString{data:vec![],long_chunks:0});}let s=d.strings.len()as u32;d.strings.push(DmString{data:format!("COST_STAGE after_call {:04x}",i.offset).into_bytes(),long_chunks:0});w.push(0x33);w.extend(V::SetCache(Box::new(V::World),Box::new(V::Field(log))).encode());w.extend([4,s,0]);}}map.insert(old.len(),w.len());for(at,to)in branches{w[at]=map[&to]as u32;}d.replace_proc_code(id,&bytecode::decode(&w).map_err(|e|format!("{e:?}"))?)?;if a.get(3).is_some_and(|x|x=="suppress-timing"){let timing=d.procs.iter().position(|p|d.string(p.strings[0])==Some(b"/proc/dq_lifecycle_time")).unwrap();d.replace_proc_code(timing,&bytecode::decode(&[0x60,0,0,0x12,0]).map_err(|e|format!("{e:?}"))?)?;}if d.strings.len()>65535{d.header.flags|=0x40000000;}d.validate_references()?;let b=d.to_bytes()?;Dmb::from_bytes(&b)?.validate_references()?;fs::create_dir_all(output.parent().unwrap())?;fs::write(&output,b)?;fs::copy(input.with_extension("rsc"),output.with_extension("rsc"))?;println!("cost stages ready timing suppression={}",a.len()>3);Ok(())}
